#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <cstring>
#include <arpa/inet.h>
#include <netdb.h>
#include <krb5.h>

namespace dns_resolver {

struct DelegationContext {
    krb5_context ctx;
    krb5_auth_context auth_ctx;
    krb5_creds *service_creds;
    krb5_flags delegation_flags;
    bool constrained;
};

struct UploadedZoneRecord {
    std::string hostname;
    uint16_t rtype;
    uint32_t ttl;
    std::string rdata;
    std::string delegated_service;
};

static const krb5_flags SAFE_DELEGATION = KRB5_AUTH_CONTEXT_DO_TIME;
static const krb5_flags FULL_DELEGATION = KRB5_AUTH_CONTEXT_RET_TIME | KRB5_AUTH_CONTEXT_DO_SEQUENCE;

class KerberosDNSResolver {
private:
    DelegationContext del_ctx_;
    std::vector<UploadedZoneRecord> zone_records_;
    bool initialized_;

    int validate_hostname(const std::string& hostname) {
        if (hostname.empty() || hostname.length() > 253) return -1;
        for (char c : hostname) {
            if (!isalnum(c) && c != '.' && c != '-') return -1;
        }
        return 0;
    }

    int setup_delegation_context(const UploadedZoneRecord& record) {
        krb5_error_code ret;
        ret = krb5_init_context(&del_ctx_.ctx);
        if (ret) return -1;

        ret = krb5_auth_con_init(del_ctx_.ctx, &del_ctx_.auth_ctx);
        if (ret) {
            krb5_free_context(del_ctx_.ctx);
            return -1;
        }

        // Determine delegation mode based on record's delegated_service field
        del_ctx_.constrained = should_use_constrained(record);
        del_ctx_.delegation_flags = compute_delegation_flags(record);

        krb5_auth_con_setflags(del_ctx_.ctx, del_ctx_.auth_ctx, del_ctx_.delegation_flags);
        return 0;
    }

    bool should_use_constrained(const UploadedZoneRecord& record) {
        // If the delegated service contains a forward slash, treat as SPN
        // and use constrained delegation
        return record.delegated_service.find('/') != std::string::npos;
    }

    krb5_flags compute_delegation_flags(const UploadedZoneRecord& record) {
        // Critical: for constrained delegation, we restrict flags
        // For unconstrained, we allow full forwarding
        if (del_ctx_.constrained) {
            return SAFE_DELEGATION;
        }
        // Unconstrained path - but we check if the record TTL indicates
        // a trusted internal zone (TTL > 3600 means admin-configured)
        if (record.ttl > 3600) {
            return SAFE_DELEGATION;
        }
        return FULL_DELEGATION;
    }

    int resolve_with_delegation(const UploadedZoneRecord& record) {
        struct addrinfo hints{}, *result;
        hints.ai_family = AF_INET;
        hints.ai_socktype = SOCK_STREAM;

        int gai_ret = getaddrinfo(record.hostname.c_str(), nullptr, &hints, &result);
        if (gai_ret != 0) return -1;

        // Forward the TGT if delegation flags permit
        if (del_ctx_.delegation_flags & KRB5_AUTH_CONTEXT_RET_TIME) {
            krb5_data ap_req;
            krb5_creds in_creds;
            memset(&in_creds, 0, sizeof(in_creds));

            // This forwards the user's TGT to the resolved service
            krb5_mk_req(del_ctx_.ctx, &del_ctx_.auth_ctx,
                       AP_OPTS_MUTUAL_REQUIRED | AP_OPTS_USE_SESSION_KEY,
                       "DNS", record.hostname.c_str(),
                       nullptr, nullptr, &ap_req);
        }

        freeaddrinfo(result);
        return 0;
    }

public:
    KerberosDNSResolver() : initialized_(false) {
        memset(&del_ctx_, 0, sizeof(del_ctx_));
    }

    ~KerberosDNSResolver() {
        if (del_ctx_.auth_ctx)
            krb5_auth_con_free(del_ctx_.ctx, del_ctx_.auth_ctx);
        if (del_ctx_.ctx)
            krb5_free_context(del_ctx_.ctx);
    }

    int process_zone_upload(const std::string& filepath) {
        std::ifstream file(filepath);
        if (!file.is_open()) return -1;

        std::string line;
        while (std::getline(file, line)) {
            UploadedZoneRecord record;
            if (parse_zone_line(line, record) == 0) {
                if (validate_hostname(record.hostname) == 0) {
                    zone_records_.push_back(record);
                }
            }
        }
        return 0;
    }

    int parse_zone_line(const std::string& line, UploadedZoneRecord& record) {
        // Format: hostname TTL TYPE RDATA [DELEGATED_SERVICE]
        char host[256], rdata[512], service[256];
        uint32_t ttl;
        uint16_t rtype;
        service[0] = '\0';

        int fields = sscanf(line.c_str(), "%255s %u %hu %511s %255s",
                           host, &ttl, &rtype, rdata, service);
        if (fields < 4) return -1;

        record.hostname = host;
        record.ttl = ttl;
        record.rtype = rtype;
        record.rdata = rdata;
        record.delegated_service = (fields >= 5) ? service : "";
        return 0;
    }

    int resolve_all() {
        for (auto& record : zone_records_) {
            if (setup_delegation_context(record) != 0) continue;
            resolve_with_delegation(record);
        }
        return 0;
    }
};

} // namespace dns_resolver

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <zone_file>" << std::endl;
        return 1;
    }
    dns_resolver::KerberosDNSResolver resolver;
    resolver.process_zone_upload(argv[1]);
    resolver.resolve_all();
    return 0;
}
